ALTER TABLE public.crm_offer_versions ADD COLUMN vat_reason text;
ALTER TABLE public.crm_orders ADD COLUMN vat_reason text, ADD COLUMN source_offer_version_id uuid REFERENCES public.crm_offer_versions(id), ADD COLUMN approval_differences jsonb, ADD COLUMN change_approval_method text, ADD COLUMN change_approval_reference text, ADD COLUMN change_approved_by uuid, ADD COLUMN change_approved_at timestamptz, ADD COLUMN billing_mode text CHECK(billing_mode IN ('start','end','installments')), ADD COLUMN billing_installments jsonb, ADD COLUMN cancelled_at timestamptz;
CREATE UNIQUE INDEX crm_orders_source_version_unique ON public.crm_orders(source_offer_version_id) WHERE source_offer_version_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.crm_contract_text(p text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT trim(regexp_replace(coalesce(p,''),'[[:space:]]+',' ','g')) $$;
CREATE OR REPLACE FUNCTION public.crm_contract_lines(p jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('line_no',(x->>'line_no')::integer,'description',public.crm_contract_text(x->>'description'),'quantity',(x->>'quantity')::numeric,'unit_price',(x->>'unit_price')::numeric) ORDER BY (x->>'line_no')::integer),'[]'::jsonb) FROM jsonb_array_elements(p) x $$;
CREATE OR REPLACE FUNCTION public.crm_contract_diff(p_before jsonb,p_after jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT coalesce(jsonb_object_agg(k,jsonb_build_object('before',p_before->k,'after',p_after->k)),'{}'::jsonb) FROM jsonb_object_keys(p_before) k WHERE p_before->k IS DISTINCT FROM p_after->k $$;
REVOKE ALL ON FUNCTION public.crm_contract_text(text),public.crm_contract_lines(jsonb),public.crm_contract_diff(jsonb,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.crm_contract_text(text),public.crm_contract_lines(jsonb),public.crm_contract_diff(jsonb,jsonb) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.crm_confirm_company_order(p_lead_id uuid,p_offer_id uuid,p_content text,p_amount numeric,p_vat_basis text,p_starts_on date,p_ends_on date,p_terms text,p_payment_terms text,p_approval_method text,p_approval_note text,p_idempotency_key text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF auth.uid() IS NULL OR NOT public.is_editor_or_admin(auth.uid()) THEN RAISE EXCEPTION 'ORDER_FORBIDDEN' USING ERRCODE='42501'; END IF;
 RAISE EXCEPTION 'ORDER_RELOAD_REQUIRED: explicit VAT and accepted version required'; END $$;
CREATE OR REPLACE FUNCTION public.crm_confirm_company_order(p_lead_id uuid,p_offer_id uuid,p_content text,p_amount numeric,p_vat_basis text,p_starts_on date,p_ends_on date,p_terms text,p_payment_terms text,p_approval_method text,p_approval_note text,p_idempotency_key text,p_source_version_id uuid,p_vat_rate numeric,p_vat_reason text,p_lines jsonb,p_billing_mode text,p_billing_installments jsonb,p_change_accepted boolean,p_change_method text,p_change_reference text,p_expected_organization_id uuid,p_expected_contact_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE me uuid:=auth.uid(); l public.booking_requests; v public.crm_offer_versions; op public.crm_order_command_ops; payload jsonb; before_doc jsonb; after_doc jsonb; diffs jsonb; src_lines jsonb; clean_lines jsonb; new_ver uuid; oid uuid; n integer; row jsonb; sum_amount numeric:=0; latest uuid; reason text:=public.crm_contract_text(p_vat_reason); mode text:=nullif(p_billing_mode,''); installments jsonb:=coalesce(p_billing_installments,'[]'::jsonb);
BEGIN
 IF me IS NULL OR NOT public.is_editor_or_admin(me) THEN RAISE EXCEPTION 'ORDER_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_idempotency_key IS NULL OR length(p_idempotency_key) NOT BETWEEN 8 AND 100 THEN RAISE EXCEPTION 'OP_KEY_REQUIRED'; END IF;
 payload:=jsonb_build_array(p_lead_id,p_offer_id,public.crm_contract_text(p_content),p_amount,p_vat_basis,p_starts_on,p_ends_on,public.crm_contract_text(p_terms),public.crm_contract_text(p_payment_terms),p_approval_method,public.crm_contract_text(p_approval_note),p_source_version_id,p_vat_rate,reason,p_lines,mode,installments,p_change_accepted,p_change_method,public.crm_contract_text(p_change_reference),p_expected_organization_id,p_expected_contact_id);
 PERFORM pg_advisory_xact_lock(hashtextextended('crm-order:'||p_idempotency_key,0));
 SELECT * INTO op FROM public.crm_order_command_ops WHERE op_key=p_idempotency_key;
 IF FOUND THEN IF op.request IS DISTINCT FROM payload THEN RAISE EXCEPTION 'OP_KEY_REUSED'; END IF; RETURN op.order_id; END IF;
 SELECT * INTO l FROM public.booking_requests WHERE id=p_lead_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'LEAD_NOT_FOUND'; END IF;
 IF l.mt_personal THEN RAISE EXCEPTION 'PERSONAL_CASE'; END IF;
 IF l.organization_id IS NULL THEN RAISE EXCEPTION 'BUYER_NOT_LINKED'; END IF;
 IF l.contact_id IS NULL THEN RAISE EXCEPTION 'CONTACT_NOT_LINKED'; END IF;
 IF l.organization_id IS DISTINCT FROM p_expected_organization_id OR l.contact_id IS DISTINCT FROM p_expected_contact_id THEN RAISE EXCEPTION 'LINK_CHANGED' USING ERRCODE='40001'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.crm_organizations WHERE id=l.organization_id AND public.crm_normalize_business_id(business_id) IS NOT NULL) THEN RAISE EXCEPTION 'BUYER_BUSINESS_ID_REQUIRED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.crm_contacts WHERE id=l.contact_id AND organization_id=l.organization_id) THEN RAISE EXCEPTION 'CONTACT_ORGANIZATION_MISMATCH'; END IF;
 IF l.owner_id IS NULL OR NOT public.staff_has_editor_role(l.owner_id) THEN RAISE EXCEPTION 'INVALID_ACCOUNT_OWNER'; END IF;
 PERFORM 1 FROM public.crm_offers WHERE id=p_offer_id AND lead_id=l.id AND status='accepted' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'OFFER_NOT_ACCEPTED'; END IF;
 SELECT * INTO v FROM public.crm_offer_versions WHERE id=p_source_version_id AND offer_id=p_offer_id AND approved_at IS NOT NULL AND approved_by IS NOT NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ACCEPTED_VERSION_REQUIRED'; END IF;
 SELECT id INTO latest FROM public.crm_offer_versions WHERE offer_id=p_offer_id AND approved_at IS NOT NULL ORDER BY version_no DESC LIMIT 1;
 IF latest IS DISTINCT FROM v.id THEN RAISE EXCEPTION 'OFFER_CHANGED' USING ERRCODE='40001'; END IF;
 IF v.organization_id IS DISTINCT FROM l.organization_id OR v.contact_id IS DISTINCT FROM l.contact_id THEN RAISE EXCEPTION 'OFFER_BUYER_CHANGED'; END IF;
 IF EXISTS(SELECT 1 FROM public.crm_orders o JOIN public.crm_offer_versions ov ON ov.id=o.offer_version_id WHERE ov.offer_id=p_offer_id) THEN RAISE EXCEPTION 'ORDER_ALREADY_CONFIRMED' USING ERRCODE='40001'; END IF;
 IF p_vat_basis IS NULL OR p_vat_basis NOT IN ('yleinen','koulutus_veroton','kaannetty','muu') THEN RAISE EXCEPTION 'VAT_SELECTION_REQUIRED'; END IF;
 IF p_vat_rate IS NULL OR p_vat_rate::text IN ('NaN','Infinity','-Infinity') OR p_vat_rate<0 OR p_vat_rate>100 OR (p_vat_basis='yleinen' AND p_vat_rate<>25.5) OR (p_vat_basis IN ('koulutus_veroton','kaannetty') AND p_vat_rate<>0) THEN RAISE EXCEPTION 'VAT_RATE_INVALID'; END IF;
 IF p_vat_basis<>'yleinen' AND reason='' THEN RAISE EXCEPTION 'VAT_REASON_REQUIRED'; END IF;
 IF p_amount IS NULL OR p_amount<=0 OR p_amount::text IN ('NaN','Infinity','-Infinity') OR p_amount<>round(p_amount,2) THEN RAISE EXCEPTION 'AMOUNT_REQUIRED'; END IF;
 IF p_starts_on IS NULL OR p_ends_on IS NULL OR NOT isfinite(p_starts_on) OR NOT isfinite(p_ends_on) OR p_ends_on<p_starts_on THEN RAISE EXCEPTION 'ORDER_DATES_INVALID'; END IF;
 IF public.crm_contract_text(p_content)='' OR public.crm_contract_text(p_terms)='' OR public.crm_contract_text(p_payment_terms)='' THEN RAISE EXCEPTION 'ORDER_CONTENT_REQUIRED'; END IF;
 IF p_approval_method IS NULL OR p_approval_method NOT IN ('sahkoposti','allekirjoitus','suullinen_muistio') OR public.crm_contract_text(p_approval_note)='' THEN RAISE EXCEPTION 'ORDER_APPROVAL_REQUIRED'; END IF;
 IF p_lines IS NULL OR jsonb_typeof(p_lines)<>'array' OR jsonb_array_length(p_lines) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'ORDER_LINES_REQUIRED'; END IF;
 FOR row IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
  IF jsonb_typeof(row)<>'object' OR jsonb_typeof(row->'quantity') IS DISTINCT FROM 'number' OR jsonb_typeof(row->'unit_price') IS DISTINCT FROM 'number' OR jsonb_typeof(row->'line_no') IS DISTINCT FROM 'number' OR (row->>'line_no')::numeric<>(row->>'line_no')::integer OR (row->>'line_no')::integer<=0 OR public.crm_contract_text(row->>'description')='' OR (row->>'quantity')::numeric<=0 OR (row->>'unit_price')::numeric<0 THEN RAISE EXCEPTION 'ORDER_LINE_INVALID'; END IF;
  sum_amount:=sum_amount+(row->>'quantity')::numeric*(row->>'unit_price')::numeric;
 END LOOP;
 IF sum_amount<>p_amount OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_lines) x GROUP BY x->>'line_no' HAVING count(*)>1) THEN RAISE EXCEPTION 'ORDER_LINE_TOTAL_MISMATCH'; END IF;
 clean_lines:=public.crm_contract_lines(p_lines);
 SELECT public.crm_contract_lines(coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) INTO src_lines FROM public.crm_offer_version_lines x WHERE version_id=v.id;
 IF jsonb_array_length(src_lines)=0 THEN RAISE EXCEPTION 'ACCEPTED_LINES_REQUIRED'; END IF;
 IF mode IS NOT NULL AND mode NOT IN ('start','end','installments') THEN RAISE EXCEPTION 'BILLING_MODE_REQUIRED'; END IF;
 IF jsonb_typeof(installments)<>'array' THEN RAISE EXCEPTION 'BILLING_INVALID_INSTALLMENTS'; END IF;
 before_doc:=jsonb_build_object('amount',(SELECT sum((x->>'quantity')::numeric*(x->>'unit_price')::numeric) FROM jsonb_array_elements(src_lines) x),'vat_basis',v.vat_basis,'vat_rate',v.vat_rate,'vat_reason',public.crm_contract_text(v.vat_reason),'content',public.crm_contract_text(v.content),'lines',src_lines,'starts_on',v.starts_on,'ends_on',v.ends_on,'terms',public.crm_contract_text(v.terms),'payment_terms',public.crm_contract_text(v.payment_terms),'billing_mode',v.billing_mode,'billing_installments',coalesce(v.billing_installments,'[]'::jsonb));
 after_doc:=jsonb_build_object('amount',p_amount,'vat_basis',p_vat_basis,'vat_rate',p_vat_rate,'vat_reason',reason,'content',public.crm_contract_text(p_content),'lines',clean_lines,'starts_on',p_starts_on,'ends_on',p_ends_on,'terms',public.crm_contract_text(p_terms),'payment_terms',public.crm_contract_text(p_payment_terms),'billing_mode',mode,'billing_installments',installments);
 diffs:=public.crm_contract_diff(before_doc,after_doc);
 IF diffs<>'{}'::jsonb AND (p_change_accepted IS DISTINCT FROM true OR p_change_method IS NULL OR p_change_method NOT IN ('sahkoposti','allekirjoitus','suullinen_muistio') OR public.crm_contract_text(p_change_reference)='') THEN RAISE EXCEPTION 'ORDER_CHANGE_APPROVAL_REQUIRED'; END IF;
 new_ver:=v.id;
 IF diffs<>'{}'::jsonb THEN
  SELECT coalesce(max(version_no),0)+1 INTO n FROM public.crm_offer_versions WHERE offer_id=p_offer_id;
  INSERT INTO public.crm_offer_versions(offer_id,version_no,organization_id,contact_id,service_key,content,vat_rate,vat_basis,vat_reason,starts_on,ends_on,terms,payment_terms,billing_mode,billing_installments) VALUES(p_offer_id,n,l.organization_id,l.contact_id,v.service_key,trim(p_content),p_vat_rate,p_vat_basis,nullif(reason,''),p_starts_on,p_ends_on,trim(p_terms),trim(p_payment_terms),mode,installments) RETURNING id INTO new_ver;
  INSERT INTO public.crm_offer_version_lines(version_id,line_no,description,quantity,unit_price) SELECT new_ver,(x->>'line_no')::integer,x->>'description',(x->>'quantity')::numeric,(x->>'unit_price')::numeric FROM jsonb_array_elements(clean_lines) x;
  UPDATE public.crm_offer_versions SET approved_at=now(),approval_method=p_change_method,approval_note=trim(p_change_reference) WHERE id=new_ver;
 END IF;
 INSERT INTO public.crm_orders(lead_id,offer_version_id,idempotency_key,organization_id,contact_id,owner_id,service_key,vat_rate,vat_basis,vat_reason,starts_on,ends_on,terms,payment_terms,total_net,confirmed_by,source_offer_version_id,approval_differences,change_approval_method,change_approval_reference,change_approved_by,change_approved_at,billing_mode,billing_installments) VALUES(l.id,new_ver,p_idempotency_key,l.organization_id,l.contact_id,l.owner_id,coalesce(v.service_key,l.service_key),p_vat_rate,p_vat_basis,nullif(reason,''),p_starts_on,p_ends_on,trim(p_terms),trim(p_payment_terms),p_amount,me,v.id,diffs,CASE WHEN diffs<>'{}'::jsonb THEN p_change_method END,CASE WHEN diffs<>'{}'::jsonb THEN trim(p_change_reference) END,CASE WHEN diffs<>'{}'::jsonb THEN me END,CASE WHEN diffs<>'{}'::jsonb THEN now() END,mode,installments) RETURNING id INTO oid;
 INSERT INTO public.crm_order_lines(order_id,line_no,description,quantity,unit_price) SELECT oid,(x->>'line_no')::integer,x->>'description',(x->>'quantity')::numeric,(x->>'unit_price')::numeric FROM jsonb_array_elements(clean_lines) x;
 IF mode IS NOT NULL THEN PERFORM public.crm_save_billing_plan(oid,mode,CASE WHEN mode='installments' THEN installments ELSE '[]'::jsonb END,0,gen_random_uuid()); END IF;
 INSERT INTO public.crm_order_command_ops(op_key,request,order_id,actor_id) VALUES(p_idempotency_key,payload,oid,me);
 RETURN oid;
END $$;
REVOKE ALL ON FUNCTION public.crm_confirm_company_order(uuid,uuid,text,numeric,text,date,date,text,text,text,text,text,uuid,numeric,text,jsonb,text,jsonb,boolean,text,text,uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.crm_confirm_company_order(uuid,uuid,text,numeric,text,date,date,text,text,text,text,text,uuid,numeric,text,jsonb,text,jsonb,boolean,text,text,uuid,uuid) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.crm_confirm_order(uuid,text) FROM authenticated;
COMMENT ON FUNCTION public.crm_confirm_order(uuid,text) IS 'Internal legacy primitive only: clients must explicitly confirm VAT and compare the accepted source through crm_confirm_company_order.';
NOTIFY pgrst,'reload schema';